    terms: [['Title', 'A catalog description of a work, which may have multiple physical copies.'], ['Copy', 'One lendable physical or digital instance of a catalog title.'], ['Loan', 'An event recording who borrowed a copy and when it was returned.'], ['Data dictionary', 'A concise record of fields, meaning, type, and constraints.']],
    mistakes: ['Using one Book row for both a title and all its physical copies.', 'Deleting returned loans and losing the history needed for reports.', 'Checking copy availability in application code without protecting concurrent checkout attempts.'],
